async function runtimeRequest(method, endpoint, body, timeoutMs = 30_000) {
  const base = (() => { const base = String($env.MERCHROUTE_RUNTIME_BASE_URL || '').trim().replace(/\/+$/, ''); if (!base) throw new Error('MERCHROUTE_RUNTIME_BASE_URL 未配置，禁止发出 MerchRoute runtime 请求'); return base; })();
  const key = String($env.MERCHROUTE_RUNTIME_KEY || '').trim();
  if (!key) throw new Error('MERCHROUTE_RUNTIME_KEY 未配置，无法访问 MerchRoute WB runtime API');
  const RuntimeURL = require('url').URL;
  const target = new RuntimeURL(base + endpoint);
  const payload = body === undefined ? '' : JSON.stringify(body);
  const transport = target.protocol === 'https:' ? require('https') : require('http');
  const response = await new Promise((resolve, reject) => {
    const request = transport.request(target, {
      method,
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-MerchRoute-Runtime-Key': key,
        ...(payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}),
      },
    }, (incoming) => {
      const chunks = [];
      let bytes = 0;
      incoming.on('data', (chunk) => {
        bytes += chunk.length;
        if (bytes > 20 * 1024 * 1024) {
          request.destroy(new Error('MerchRoute runtime API 响应超过 20 MiB 限制'));
          return;
        }
        chunks.push(chunk);
      });
      incoming.on('end', () => resolve({
        status: Number(incoming.statusCode || 0),
        text: Buffer.concat(chunks).toString('utf8'),
      }));
    });
    const boundedTimeoutMs = Math.max(1_000, Math.min(180_000, Number(timeoutMs) || 30_000));
    request.setTimeout(boundedTimeoutMs, () => request.destroy(new Error('MerchRoute runtime API 请求超时')));
    request.on('error', reject);
    if (payload) request.write(payload);
    request.end();
  });
  const text = response.text;
  let data = {};
  if (text) {
    try { data = JSON.parse(text); } catch (_) { data = { raw: text }; }
  }
  if (response.status < 200 || response.status >= 300) {
    const nestedError = data && typeof data.error === 'object' && data.error !== null ? data.error : {};
    const errorValue = typeof data.error === 'string' ? data.error : '';
    const error = new Error(String(data.message || nestedError.message || errorValue || data.code || nestedError.code || ('MerchRoute runtime API HTTP ' + response.status)));
    error.code = String(data.code || nestedError.code || errorValue || 'RUNTIME_API_FAILED');
    error.httpStatus = response.status;
    error.details = data;
    throw error;
  }
  return data;
}
function toItems(value) {
  const rows = Array.isArray(value) ? value : value == null ? [] : [value];
  return rows.map((row) => ({ json: row || {} }));
}
function migrated(name) {
  return [{ json: { ok: false, migrated: true, error: 'MIGRATED_TO_POSTGRESQL', code: 'MIGRATED_TO_POSTGRESQL', message: name + ' 已迁移到 MerchRoute PostgreSQL runtime API' } }];
}
function runtimeFailureDetails(error) {
  const queue = [error];
  const seen = new Set();
  const codes = [];
  const messages = [];
  const statuses = [];
  while (queue.length && seen.size < 16) {
    const current = queue.shift();
    if (!current || typeof current !== 'object' || seen.has(current)) continue;
    seen.add(current);
    for (const key of ['code','errno','errorCode']) if (current[key] != null) codes.push(String(current[key]).toUpperCase());
    for (const key of ['message','description']) if (current[key]) messages.push(String(current[key]));
    for (const key of ['httpStatus','statusCode','httpCode','status']) {
      if (current[key] == null) continue;
      const status = Number(current[key]);
      if (Number.isFinite(status)) statuses.push(status);
    }
    for (const key of ['cause','error','originalError']) {
      if (current[key] && typeof current[key] === 'object') queue.push(current[key]);
    }
  }
  return { codes, messages, statuses };
}
function isRuntimeNetworkFailure(error) {
  const details = runtimeFailureDetails(error);
  const retryableCodes = new Set([
    'ETIMEDOUT','ESOCKETTIMEDOUT','ECONNRESET','ECONNABORTED','ECONNREFUSED','ENOTFOUND','EAI_AGAIN','EPIPE',
    'UND_ERR_CONNECT_TIMEOUT','UND_ERR_HEADERS_TIMEOUT','UND_ERR_BODY_TIMEOUT','UND_ERR_SOCKET',
  ]);
  if (details.codes.some((code) => retryableCodes.has(code))) return true;
  if (details.statuses.some((status) => [408, 425, 429].includes(status) || status >= 500)) return true;
  const message = details.messages.join(' | ');
  return /\b(?:ETIMEDOUT|ESOCKETTIMEDOUT|ECONNRESET|ECONNABORTED|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EPIPE|UND_ERR_CONNECT_TIMEOUT|UND_ERR_HEADERS_TIMEOUT|UND_ERR_BODY_TIMEOUT|UND_ERR_SOCKET)\b|fetch failed|failed to fetch|timed?\s*out|请求超时|socket hang up|temporary tls eof|network socket disconnected/i.test(message);
}
function persistentNetworkDelaySeconds(attempt) {
  const schedule = [30, 60, 300, 900];
  return schedule[Math.min(Math.max(1, Number(attempt || 1)), schedule.length) - 1];
}

return (async () => {
  const values = {};
  values["config_id"] = "default";
  if ("wb_runtime_config" === 'wb_runtime_config') {
    if ("Load Runtime Config" === 'Load Dispatch Config') {
      const gate = $getWorkflowStaticData('global');
      gate.runtimeNetworkRecovery = gate.runtimeNetworkRecovery && typeof gate.runtimeNetworkRecovery === 'object'
        ? gate.runtimeNetworkRecovery : {};
      const recovery = gate.runtimeNetworkRecovery;
      if (recovery.active === true && Number.isFinite(Date.parse(String(recovery.nextAttemptAt || '')))
          && Date.parse(String(recovery.nextAttemptAt)) > Date.now()) {
        return [{ json: { __runtimeNetworkWait: true, networkRecovery: recovery } }];
      }
      try {
        const data = await runtimeRequest('GET', '/api/v1/wb/runtime/config', undefined);
        if (recovery.active === true) {
          gate.runtimeNetworkRecovery = {
            ...recovery, active: false, recoveredAt: new Date().toISOString(), nextAttemptAt: null,
          };
        }
        return toItems(data.config || data);
      } catch (error) {
        if (!isRuntimeNetworkFailure(error)) throw error;
        const attempt = recovery.active === true ? Number(recovery.attempt || 0) + 1 : 1;
        const delaySeconds = persistentNetworkDelaySeconds(attempt);
        gate.runtimeNetworkRecovery = {
          active: true, phase: 'WB_RUNTIME_CONFIG', resumeState: 'DISPATCH', attempt,
          pauseStartedAt: recovery.pauseStartedAt || new Date().toISOString(),
          lastFailureAt: new Date().toISOString(),
          nextAttemptAt: new Date(Date.now() + delaySeconds * 1000).toISOString(),
          lastErrorCode: String(error?.code || 'RUNTIME_NETWORK_ERROR'),
          lastErrorMessage: String(error?.message || 'MerchRoute runtime API 网络不可用').slice(0, 1000),
        };
        return [{ json: { __runtimeNetworkWait: true, networkRecovery: gate.runtimeNetworkRecovery } }];
      }
    }
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/config', undefined);
    return toItems(data.config || data);
  }
  if ("wb_runtime_config" === 'wb_publish_jobs') {
    if (values.task_id) {
      try {
        const data = await runtimeRequest('GET', '/api/v1/wb/runtime/jobs/' + encodeURIComponent(String(values.task_id)), undefined);
        return toItems(data.job || data);
      } catch (error) {
        if ("Load Runtime Config" === 'Lookup Job Status' && Number(error.httpStatus || 0) === 404) {
          return [{ json: { __runtimeJobNotFound: true, task_id_requested: String(values.task_id) } }];
        }
        throw error;
      }
    }
    const params = ['pageSize=100'];
    if (values.product_code) params.push('productCode=' + encodeURIComponent(String(values.product_code)));
    if (values.store_id) params.push('storeId=' + encodeURIComponent(String(values.store_id)));
    if ("Load Runtime Config".includes('Dispatch')) params.push('due=true');
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/jobs?' + params.join('&'), undefined);
    const rows = Array.isArray(data.items) ? data.items : [];
    if ("Load Runtime Config" === 'Get Product Jobs' && rows.length === 0) {
      return [{ json: { __emptyProductJobs: true } }];
    }
    return toItems(rows);
  }
  if ("wb_runtime_config" === 'wb_product_registry') {
    if (!values.product_code) return [];
    const params = ['productCode=' + encodeURIComponent(String(values.product_code))];
    if (values.store_id) params.push('storeId=' + encodeURIComponent(String(values.store_id)));
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/registry?' + params.join('&'), undefined);
    return toItems(data.items || []);
  }
  if ("wb_runtime_config" === 'wb_category_templates') {
    if (!values.category_key) return [];
    const data = await runtimeRequest('GET', '/api/v1/wb/runtime/categories/' + encodeURIComponent(String(values.category_key)), undefined);
    return toItems(data.category || data);
  }
  return migrated("Load Runtime Config");
})();

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function fail(code, message) {
  const conflictCodes = new Set(['STORE_READY_MARKER_MISSING','STORE_READY_MARKER_INVALID','STORE_READY_MARKER_MISMATCH','SOURCE_CONTENT_MISMATCH','READY_SCOPE_CONFLICT','READY_MARKER_MISSING','REQUEST_REVISION_MISMATCH','REQUEST_IDEMPOTENCY_KEY_MISMATCH']);
  const envelope = {
    code: String(code || 'INTAKE_FAILED'), message: String(message || '目录声明失败'), stage: 'INSPECT_PRODUCT_FOLDER',
    httpStatus: conflictCodes.has(String(code || '')) ? 409 : 400, retryable: false, deliveryUnknown: false,
